async function api(path,method='GET',body){
  let r;
  try{r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(20000)});}
  catch(error){throw Error(error.name==='TimeoutError'?'The request took too long. Check whether your changes were saved before trying again.':'Unable to connect. Check your internet connection and try again.');}
  let d;try{d=await r.json();}catch{throw Error('The server returned an unexpected response. Please try again shortly.');}
  if(!r.ok)throw Error(d.error||'Unable to complete this action. Please try again.');return d;
}
let toastTimer;
function dismissToast(){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.classList.remove('show');el.inert=true;}
function toast(msg,type='success'){
  clearTimeout(toastTimer);const el=document.querySelector('#toast');el.inert=false;
  el.classList.toggle('error',type==='error');el.setAttribute('role',type==='error'?'alert':'status');el.setAttribute('aria-live',type==='error'?'assertive':'polite');
  el.querySelector('.toast-message').textContent=msg;el.classList.add('show');
  toastTimer=setTimeout(dismissToast,type==='error'?6500:4500);
}
const errorToast=msg=>toast(msg,'error');
let invalidCycle=false;
document.addEventListener('invalid',event=>{
  event.preventDefault();if(invalidCycle)return;invalidCycle=true;setTimeout(()=>{invalidCycle=false;},0);
  const field=event.target,label=field.closest('label')?.textContent.trim()||field.getAttribute('aria-label')||field.name||'This field';
  const message=label+': '+field.validationMessage;
  const inline=field.form?.querySelector('.form-error');if(inline)inline.textContent=message;
  errorToast(message);field.focus();
},true);

const field=(label,name,value='',type='text',required=false,extra='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;
