function layoutMarkup(type,layout){
  const existing=session.store?.details||draft.details;
  const details={...existing,name:existing.name||'Your store',description:existing.description||'Beautiful products. A store that feels like you.',deliveryInfo:existing.deliveryInfo||'Delivered across Pakistan.',address:existing.address||'Your business address',whatsapp:existing.whatsapp||'923001234567',delivery:Number(existing.delivery)||200};
  const content=(session.store?.sections||draft.sections).find(x=>x.type===type)||{};
  const theme=themeForDetails(details),samples=theme.samples.map((name,i)=>({...sampleProducts[i],details:{...sampleProducts[i].details,name,category:theme.category}}));return renderSection({...content,type,layout},details,samples);
}
function previewCanvas(type,layout,large=false){return `<div class="layout-preview ${large?'large-layout-preview':''}" aria-hidden="true" inert><div class="preview-canvas storefront" data-theme="${esc((session.store?.details||draft.details).theme||'classic')}" style="${themeStyle(session.store?.details||draft.details)}">${layoutMarkup(type,layout)}</div></div>`;}
function themeStyle(details){const theme=themeForDetails(details);const accent=/^#[a-f0-9]{6}$/i.test(details.accent)?details.accent:theme.accent;return `--brand:${accent};--store-bg:${theme.background};--store-ink:${theme.ink}`;}
function refreshThemeSuggestion(form,auto=false){
 const values=formValues(form),key=themeForNiche(values.category,values.niche);
 const themeSelect=form.querySelector('[name=theme]'),color=form.querySelector('[name=accent]');
 const previous=themeSelect.value;
 const customColor=form.dataset.accentCustom==='true'||color.value!==themes[previous].accent;
 if(auto&&form.dataset.themeCustom!=='true'){themeSelect.value=key;themeSelect.dataset.previousTheme=key;form.dataset.activeTheme=key;if(!customColor)color.value=themes[key].accent;}
 const summary=form.querySelector('[data-theme-suggestion]');if(summary)summary.outerHTML=themeSuggestion(values);
}
function suggestedSections(){
 const form=document.querySelector('#editor-form')||document.querySelector('#signup-form');
 const details=session.store?.details||draft.details,key=themeForNiche(details.category,details.niche),preset=themes[key];
 const values=formValues(form),previous=session.store?.sections||draft.sections;
 const selected=preset.sections.map(section=>{const existing=previous.find(s=>s.type===section.type);return {...existing,...section,title:values['title-'+section.type]??existing?.title??'',text:values['text-'+section.type]??existing?.text??''};});
 if(form.id==='signup-form'){draft.sections=selected;draft.sectionsCustomized=true;signup();translatePublic();}
 else{session.store.sections=selected;form.querySelector('.section-picker').outerHTML=sectionPicker(selected);form.querySelector('.section-order').innerHTML=sectionOrderMarkup(selected);toast('Suggested sections selected. Save homepage to apply them.');}
}
function themeSuggestion(details){const key=themeForNiche(details.category,details.niche),theme=themes[key];return `<div class="theme-suggestion" data-theme-suggestion><div><span class="eyebrow">CURATED FOR YOUR BUSINESS</span><h3>${theme.category} · ${theme.name}</h3><p>Suggested colors, section layouts and a matching visual style. You can customize everything.</p><div class="theme-swatches">${[theme.accent,theme.background,theme.ink].map(color=>`<span style="background:${color}" title="${color}"></span>`).join('')}</div></div><button type="button" class="btn secondary small" data-action="apply-theme-colors">Use suggested theme</button></div>`;}
function recommendationBanner(details){const key=themeForNiche(details.category,details.niche),theme=themes[key];return `<div class="theme-suggestion"><div><span class="eyebrow">RECOMMENDED FOR YOUR NICHE</span><h3>${theme.name}</h3><p>Recommended sections are marked below. All sections remain available.</p></div><button type="button" class="btn secondary small" data-action="suggest-sections">Use suggested sections</button></div>`;}
function sectionOrderMarkup(list){return list.map((x,i)=>`<div><b>${sectionNames[x.type]}</b><button type="button" data-move="${i}" data-direction="-1" ${i===0?'disabled':''}>↑</button><button type="button" data-move="${i}" data-direction="1" ${i===list.length-1?'disabled':''}>↓</button></div>`).join('');}
